function activityQuery(){return{source:val('activitySource'),category:val('activityCategory'),status:val('activityStatus'),limit:val('activityLimit')||'100',cursor:activityPager.cursor||undefined,actor:val('activityActor')||undefined,agent:val('activityAgent')||'all',thread:val('activityThread')||undefined,workspace:val('activityWorkspace')||undefined,type:val('activityType')||undefined,since:val('activitySince')||undefined}}
async function loadActivity(reset=true){if(reset)activityPager.reset();setLoading('activityList','Loading activity...');const data=await api('/api/activity',{query:activityQuery()});state.activityEvents=data.events||[];renderActivity(state.activityEvents);activityPager.render(data.pagination||{})}
function activityWorkspace(e){const active=state.snapshot?.session;return e.workspace||(active?.threadId&&e.threadId===active.threadId?active.workspace:'')}
function activityActorText(e){const a=e.actor||{};return a.label||a.username||a.id||({web:'Web user',telegram:'Telegram user',discord:'Discord user',slack:'Slack user',cli:'CLI',system:'System'}[a.channel]||'System')}
function activityMetaHtml(e){const workspace=activityWorkspace(e);const duration=typeof e.durationMs==='number'?fmtDuration(e.durationMs):'';const actor=activityActorText(e);const parts=[];if(actor)parts.push('User: '+esc(actor));if(e.correlationId)parts.push(uiTraceControls(e.correlationId));if(e.threadId)parts.push(uiCopyButton(e.threadId,'Thread ID copied'));if(workspace)parts.push(esc(workspace));if(duration)parts.push(esc(duration));return parts.join(' | ')}
function activityCell(label,html,cls=''){return '<td data-label="'+attr(label)+'"'+(cls?' class="'+cls+'"':'')+'>'+html+'</td>'}
function activityAgeHtml(e){return '<span class="activity-age" data-activity-age-at="'+attr(e.timestamp||'')+'" title="'+attr(fmtDate(e.timestamp))+'">'+esc(fmtRelativeAgo(e.timestamp))+'</span>'}
function activityStatusClass(status){if(status==='failed'||status==='aborted')return'error';if(status==='queued'||status==='running')return'warn';return''}
function activityContextHtml(e){const workspace=activityWorkspace(e);const duration=typeof e.durationMs==='number'?fmtDuration(e.durationMs):'';const parts=[];if(e.agentId)parts.push('<span class="truncate-cell" title="'+attr(e.agentId)+'">'+esc(e.agentId)+'</span>');if(e.threadId)parts.push('<button type="button" class="copy-id" data-copy-value="'+attr(e.threadId)+'" data-copy-label="Thread ID copied" title="'+attr(e.threadId)+'">'+esc(shortMiddle(e.threadId))+'</button>');if(workspace)parts.push('<span class="truncate-cell" title="'+attr(workspace)+'">'+esc(short(workspace,120))+'</span>');if(duration)parts.push('<span>'+esc(duration)+'</span>');if(e.correlationId)parts.push('<span>CID '+uiCopyButton(e.correlationId,'Correlation ID copied')+'</span>');return parts.length?'<div class="activity-context">'+parts.join('')+'</div>':'-'}
function renderActivityRow(e){const type=[e.category,e.type].filter(Boolean).join(' / ')||'-';const detail=e.prompt||e.detail||'';const status='<span class="chip '+activityStatusClass(e.status)+'">'+esc(e.status||'-')+'</span>';const actions=e.correlationId?'<div class="data-table-actions"><button type="button" class="secondary" data-trace-id="'+attr(e.correlationId)+'">Trace</button></div>':'-';return '<tr>'+activityCell('Time',activityAgeHtml(e),'updated-cell')+activityCell('Source',esc(e.source||'-'))+activityCell('Status',status,'status-cell')+activityCell('Type','<span class="truncate-cell" title="'+attr(type)+'">'+esc(short(type,80))+'</span>','type-cell')+activityCell('User','<span class="truncate-cell" title="'+attr(activityActorText(e))+'">'+esc(short(activityActorText(e),80))+'</span>','user-cell')+activityCell('Context',activityContextHtml(e),'context-cell')+activityCell('Detail','<span class="truncate-cell" title="'+attr(detail)+'">'+esc(short(detail||'-',220))+'</span>','detail-cell')+activityCell('Actions',actions,'actions-cell')+'</tr>'}
function renderActivityTable(events){renderIncrementalTable('activityList',events||[],{key:'activity-table',emptyText:'No activity.',tableClass:'activity-table',tableClassHtml:'class="data-table activity-table"',headHtml:'<tr><th>Time</th><th>Source</th><th>Status</th><th>Type</th><th>User</th><th>Context</th><th>Detail</th><th class="actions-heading">Actions</th></tr>',renderItem:renderActivityRow,initialCount:80,batchSize:80,onDone:bindActivityTable})}
function bindActivityTable(root=document){bindUiCopyButtons(root);bindUiTraceButtons(root);startActivityAgeCounter()}
function renderActivity(events){renderActivityTable(events||[])}
document.getElementById('loadActivityBtn').onclick=()=>loadActivity(true);
document.getElementById('activitySince').onchange=()=>loadActivity(true);
document.getElementById('exportActivityBtn').onclick=()=>{const rows=(state.activityEvents||[]).map(e=>[e.timestamp,e.source,e.category||'',e.status,e.type,activityActorText(e),e.agentId||'',e.threadId||'',activityWorkspace(e),e.prompt||e.detail||''].join('\\t')).join('\\n');const blob=new Blob([rows],{type:'text/tab-separated-values'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='nordrelay-activity.tsv';a.click();URL.revokeObjectURL(a.href)};
function renderTracePlaceholder(){const target=document.getElementById('traceDetail');if(target&&!target.innerHTML)target.innerHTML='<div class="item">Enter a correlation ID or open Trace from Activity/Tasks.</div>'}
async function openTrace(correlationId){document.getElementById('traceCorrelationId').value=correlationId;switchMonitorTab('trace');page('monitor');await loadTrace(correlationId)}
async function loadTrace(correlationId=val('traceCorrelationId')){if(!correlationId){renderTracePlaceholder();return}setLoading('traceDetail','Loading trace...');const data=await api('/api/trace',{query:{correlationId}});renderTrace(data)}
function traceAgeHtml(item){return '<span class="activity-age" data-activity-age-at="'+attr(item.at||'')+'" title="'+attr(fmtDate(item.at))+'">'+esc(fmtRelativeAgo(item.at))+'</span>'}
function traceContextHtml(item){const parts=[];if(item.agentId)parts.push('<span class="truncate-cell" title="'+attr(item.agentId)+'">'+esc(item.agentId)+'</span>');if(item.threadId)parts.push('<button type="button" class="copy-id" data-copy-value="'+attr(item.threadId)+'" data-copy-label="Thread ID copied" title="'+attr(item.threadId)+'">'+esc(shortMiddle(item.threadId))+'</button>');if(item.workspace)parts.push('<span class="truncate-cell" title="'+attr(item.workspace)+'">'+esc(short(item.workspace,120))+'</span>');return parts.length?'<div class="activity-context">'+parts.join('')+'</div>':'-'}
function renderTraceTimelineRow(item){const status='<span class="chip '+activityStatusClass(item.status)+'">'+esc(item.status||'-')+'</span>';const action=item.id?'<div class="data-table-actions"><button type="button" class="secondary" data-copy-value="'+attr(item.id)+'" data-copy-label="Trace event ID copied">Copy ID</button></div>':'-';return '<tr>'+activityCell('Time',traceAgeHtml(item),'updated-cell')+activityCell('Source',esc(item.source||'-'))+activityCell('Status',status,'status-cell')+activityCell('Type','<span class="truncate-cell" title="'+attr(item.type||'')+'">'+esc(short(item.type||'-',80))+'</span>','type-cell')+activityCell('Title','<span class="truncate-cell" title="'+attr(item.title||'')+'">'+esc(short(item.title||'-',120))+'</span>','user-cell')+activityCell('Context',traceContextHtml(item),'context-cell')+activityCell('Detail','<span class="truncate-cell" title="'+attr(item.detail||'')+'">'+esc(short(item.detail||'-',220))+'</span>','detail-cell')+activityCell('Actions',action,'actions-cell')+'</tr>'}
function renderTraceTimelineTable(timeline){if(!timeline.length)return uiEmpty('No events for this correlation ID.');return '<div class="data-table-wrap"><table class="data-table activity-table trace-table"><thead><tr><th>Time</th><th>Source</th><th>Status</th><th>Type</th><th>Title</th><th>Context</th><th>Detail</th><th class="actions-heading">Actions</th></tr></thead><tbody>'+timeline.map(renderTraceTimelineRow).join('')+'</tbody></table></div>'}
function renderTrace(data){const s=data.summary||{};const rows=[['Correlation ID',data.correlationId],['Status',s.status],['Started',fmtDate(s.startedAt)],['Updated',fmtDate(s.updatedAt)],['Agent',s.agentId],['Thread',s.threadId],['Workspace',s.workspace],['Sources',(s.sources||[]).join(', ')]];const target=document.getElementById('traceDetail');target.innerHTML=card('Trace summary',rows)+'<h2 class="task-section-title">Timeline</h2>'+renderTraceTimelineTable(data.timeline||[]);bindUiCopyButtons(target);startActivityAgeCounter()}
document.getElementById('loadTraceBtn').onclick=()=>loadTrace();
document.getElementById('traceCorrelationId').addEventListener('keydown',e=>{if(e.key==='Enter')loadTrace()});
function monitorTabPermission(tab){return{activity:'sessions.read',tasks:'inspect',trace:'sessions.read',artifacts:'files.read'}[tab]||'inspect'}
function firstAllowedMonitorTab(){return['activity','tasks','trace','artifacts'].find(tab=>can(monitorTabPermission(tab)))||'tasks'}
function ensureMonitorTabAllowed(){if(!can(monitorTabPermission(state.monitorTab)))state.monitorTab=firstAllowedMonitorTab()}
function switchMonitorTab(tab){state.monitorTab=tab||'activity';ensureMonitorTabAllowed();if(state.monitorTab!=='activity'&&state.monitorTab!=='tasks')stopActivityAgeCounter();document.querySelectorAll('[data-monitor-tab]').forEach(b=>{const active=b.dataset.monitorTab===state.monitorTab;b.classList.toggle('active',active);b.setAttribute('aria-selected',active?'true':'false');b.tabIndex=active?0:-1});document.querySelectorAll('[data-monitor-tab-panel]').forEach(panel=>panel.classList.toggle('active',panel.dataset.monitorTabPanel===state.monitorTab))}
function bindMonitorTabs(){document.querySelectorAll('[data-monitor-tab]').forEach(b=>{if(b.dataset.bound)return;b.dataset.bound='true';b.onclick=()=>safe(async()=>{switchMonitorTab(b.dataset.monitorTab);await loadMonitorTab()})})}
async function loadMonitor(){bindMonitorTabs();ensureMonitorTabAllowed();switchMonitorTab(state.monitorTab||'activity');await loadMonitorTab()}
async function loadMonitorTab(){const tab=state.monitorTab||'activity';if(!can(monitorTabPermission(tab))){const panel=document.querySelector('[data-monitor-tab-panel="'+cssEscape(tab)+'"] .list');if(panel)panel.innerHTML=uiEmpty('Permission required: '+monitorTabPermission(tab));return}if(tab==='activity')await loadActivity(true);else if(tab==='tasks')await loadTasks(true);else if(tab==='trace')renderTracePlaceholder();else if(tab==='artifacts')await loadArtifacts(true)}
async function loadAccess(){if(!can('users.read')){document.getElementById('accessPanel').innerHTML='<div class="item">Permission required: users.read</div>';return}setLoading('accessPanel','Loading users...');const d=await api('/api/users');state.userManagement=d;renderUserManagement(d);bindAccessTabs();switchAccessTab(state.accessTab||'users');if(can('sessions.read'))await loadLocks();else document.getElementById('locksList').innerHTML='<div class="item">Permission required: sessions.read</div>';if(can('audit.read'))await loadAudit();else document.getElementById('auditList').innerHTML='<div class="item">Permission required: audit.read</div>'}
document.getElementById('loadAccessBtn').onclick=()=>loadAccess();
function groupOptions(selected=[]){const selectedSet=new Set(selected);return (state.userManagement?.groups||[]).map(g=>'<label class="checkbox"><input type="checkbox" data-group-choice="'+attr(g.id)+'" '+(selectedSet.has(g.id)?'checked':'')+'> '+esc(g.name)+'</label>').join('')}
const ARTIFACT_DELIVERY_MODES=['manual-only','summary','summary-with-actions','auto-files','auto-zip','images-only','off'];
function artifactDeliverySelect(id,selected='',label='Artifact delivery',inherit='Use default'){return '<label>'+esc(label)+'<select id="'+attr(id)+'"><option value="" '+(!selected?'selected':'')+'>'+esc(inherit)+'</option>'+ARTIFACT_DELIVERY_MODES.map(mode=>'<option value="'+attr(mode)+'" '+(selected===mode?'selected':'')+'>'+esc(mode)+'</option>').join('')+'</select></label>'}
function permissionOptions(selected=[]){const selectedSet=new Set(selected);return '<div class="permission-grid full-span">'+(state.userManagement?.permissions||[]).map(p=>'<label class="checkbox"><input type="checkbox" data-permission-choice="'+attr(p)+'" '+(selectedSet.has(p)?'checked':'')+'> '+esc(p)+'</label>').join('')+'</div>'}
function selectedValues(selector){return Array.from(document.querySelectorAll(selector+':checked')).map(x=>x.dataset.groupChoice||x.dataset.permissionChoice||x.dataset.discordChannelChoice||x.dataset.slackChannelChoice||x.value).filter(Boolean)}
function csv(values=[]){return (values||[]).join(', ')}
function adminDialog(title,body,onSubmit,options:any={}){const dialog=document.getElementById('adminDialog');document.getElementById('adminDialogTitle').textContent=title;document.getElementById('adminDialogBody').innerHTML=body;document.getElementById('adminDialogSubmit').textContent=options.submitText||'Save';document.getElementById('adminDialogCancel').onclick=()=>dialog.close();document.getElementById('adminDialogForm').onsubmit=e=>safe(async()=>{e.preventDefault();await onSubmit();dialog.close();if(options.afterSubmit)await options.afterSubmit();else if(options.reloadAccess!==false)await loadAccess()},e);dialog.showModal()}
function userGroups(u){return (u.groups||[]).map(g=>g.id)}
function accessCopyButton(value,label='Copied'){return value?'<button type="button" class="copy-id" data-access-copy="'+attr(value)+'" data-access-copy-label="'+attr(label)+'">'+esc(value)+'</button>':'-'}
function bindAccessCopyButtons(){document.querySelectorAll('[data-access-copy]').forEach(b=>b.onclick=()=>copyText(b.dataset.accessCopy||'',b.dataset.accessCopyLabel||'Copied'))}
function bindAccessTabs(){document.querySelectorAll('[data-access-tab]').forEach(b=>b.onclick=()=>switchAccessTab(b.dataset.accessTab));const discordSearch=document.getElementById('discordChannelSearch');if(discordSearch&&!discordSearch.dataset.bound){discordSearch.dataset.bound='true';discordSearch.oninput=()=>renderDiscordChannels()}const slackSearch=document.getElementById('slackChannelSearch');if(slackSearch&&!slackSearch.dataset.bound){slackSearch.dataset.bound='true';slackSearch.oninput=()=>renderSlackChannels()}}
function switchAccessTab(tab){state.accessTab=tab||'users';document.querySelectorAll('[data-access-tab]').forEach(b=>b.classList.toggle('active',b.dataset.accessTab===state.accessTab));document.querySelectorAll('[data-access-tab-panel]').forEach(panel=>panel.classList.toggle('active',panel.dataset.accessTabPanel===state.accessTab))}
function groupNames(ids=[]){const groups:any=state.userManagement?.groups||[];return (ids||[]).map(id=>groups.find(g=>g.id===id)?.name||id).join(', ')}
function discordChannelLabel(channel){return channel.title?channel.title+' ('+channel.channelId+')':channel.channelId}
function discordScopeLabel(ids=[]){const channels=state.userManagement?.discordChannels||[];return (ids||[]).map(id=>discordChannelLabel(channels.find(c=>c.channelId===id)||{channelId:id})).join(', ')}
function discordChannelOptions(selected=[]){const selectedSet=new Set(selected||[]);const channels=state.userManagement?.discordChannels||[];return '<div class="permission-grid full-span">'+(channels.map(c=>'<label class="checkbox"><input type="checkbox" data-discord-channel-choice="'+attr(c.channelId)+'" '+(selectedSet.has(c.channelId)?'checked':'')+'> '+esc(discordChannelLabel(c)+' / '+(c.guildId||'DM'))+'</label>').join('')||'<small>No Discord channels registered.</small>')+'</div>'}
function discordIdentityHtml(user,identity){const id=String(identity.discordUserId||'');return '<span class="access-id-row">'+accessCopyButton(id,'Discord user ID copied')+(identity.username?' <span>@'+esc(identity.username)+'</span>':'')+' <button class="secondary mini-button" data-discord-user="'+attr(user.id)+'" data-discord-unlink="'+attr(identity.id)+'"'+disabledAttr('users.write')+'>Unlink</button></span>'}
function renderDiscordChannels(channels=state.userManagement?.discordChannels||[]){const target=document.getElementById('discordChannelsList');if(!target)return;const query=(document.getElementById('discordChannelSearch')?.value||'').toLowerCase();const filtered=(channels||[]).filter(c=>!query||[c.title,c.channelId,c.guildId,c.type,groupNames(c.allowedGroupIds)].filter(Boolean).join(' ').toLowerCase().includes(query));target.innerHTML=filtered.map(c=>'<div class="item"><strong>'+esc(c.title||String(c.channelId))+' <span class="adapter-status '+(c.enabled?'enabled':'disabled')+'">'+(c.enabled?'enabled':'disabled')+'</span></strong><small class="access-id-row">Channel ID: '+accessCopyButton(c.channelId,'Discord channel ID copied')+'</small><small class="access-id-row">Guild ID: '+accessCopyButton(c.guildId||'','Discord guild ID copied')+'</small><small>'+esc('Type: '+(c.type||'-'))+'</small><small>Groups: '+esc(groupNames(c.allowedGroupIds)||'all groups')+'</small><div class="row"><button data-discord-channel-edit="'+attr(c.id)+'"'+disabledAttr('users.write')+'>Edit</button><button class="secondary" data-discord-channel-toggle="'+attr(c.id)+'"'+disabledAttr('users.write')+'>'+(c.enabled?'Disable':'Enable')+'</button></div></div>').join('')||'<div class="item">No Discord channels registered.</div>';bindDiscordChannelButtons();bindAccessCopyButtons();applyPermissions()}
function slackChannelLabel(channel){return channel.title?channel.title+' ('+channel.channelId+')':channel.channelId}
function slackScopeLabel(ids=[]){const channels=state.userManagement?.slackChannels||[];return (ids||[]).map(id=>slackChannelLabel(channels.find(c=>c.channelId===id)||{channelId:id})).join(', ')}
function slackChannelOptions(selected=[]){const selectedSet=new Set(selected||[]);const channels=state.userManagement?.slackChannels||[];return '<div class="permission-grid full-span">'+(channels.map(c=>'<label class="checkbox"><input type="checkbox" data-slack-channel-choice="'+attr(c.channelId)+'" '+(selectedSet.has(c.channelId)?'checked':'')+'> '+esc(slackChannelLabel(c)+' / '+(c.teamId||'team default'))+'</label>').join('')||'<small>No Slack channels registered.</small>')+'</div>'}
function slackIdentityHtml(user,identity){const id=String(identity.slackUserId||'');const team=identity.teamId?' <span>'+esc(identity.teamId)+'</span>':'';return '<span class="access-id-row">'+accessCopyButton(id,'Slack user ID copied')+team+(identity.username?' <span>@'+esc(identity.username)+'</span>':'')+' <button class="secondary mini-button" data-slack-user="'+attr(user.id)+'" data-slack-unlink="'+attr(identity.id)+'"'+disabledAttr('users.write')+'>Unlink</button></span>'}
function renderSlackChannels(channels=state.userManagement?.slackChannels||[]){const target=document.getElementById('slackChannelsList');if(!target)return;const query=(document.getElementById('slackChannelSearch')?.value||'').toLowerCase();const filtered=(channels||[]).filter(c=>!query||[c.title,c.channelId,c.teamId,c.type,groupNames(c.allowedGroupIds)].filter(Boolean).join(' ').toLowerCase().includes(query));target.innerHTML=filtered.map(c=>'<div class="item"><strong>'+esc(c.title||String(c.channelId))+' <span class="adapter-status '+(c.enabled?'enabled':'disabled')+'">'+(c.enabled?'enabled':'disabled')+'</span></strong><small class="access-id-row">Channel ID: '+accessCopyButton(c.channelId,'Slack channel ID copied')+'</small><small class="access-id-row">Team ID: '+accessCopyButton(c.teamId||'','Slack team ID copied')+'</small><small>'+esc('Type: '+(c.type||'-'))+'</small><small>Groups: '+esc(groupNames(c.allowedGroupIds)||'all groups')+'</small><div class="row"><button data-slack-channel-edit="'+attr(c.id)+'"'+disabledAttr('users.write')+'>Edit</button><button class="secondary" data-slack-channel-toggle="'+attr(c.id)+'"'+disabledAttr('users.write')+'>'+(c.enabled?'Disable':'Enable')+'</button></div></div>').join('')||'<div class="item">No Slack channels registered.</div>';bindSlackChannelButtons();bindAccessCopyButtons();applyPermissions()}
function renderUserManagement(d){document.getElementById('accessPanel').innerHTML=(d.users||[]).map(u=>{const telegram=(u.telegramIdentities||[]).map(t=>t.telegramUserId+(t.username?' @'+t.username:'')+' <button class="secondary mini-button" data-telegram-user="'+attr(u.id)+'" data-telegram-unlink="'+attr(t.id)+'"'+disabledAttr('users.write')+'>Unlink</button>').join(' ');const discord=(u.discordIdentities||[]).map(identity=>discordIdentityHtml(u,identity)).join(' ');const slack=(u.slackIdentities||[]).map(identity=>slackIdentityHtml(u,identity)).join(' ');return '<div class="item"><strong>'+esc(u.displayName)+' <span class="adapter-status '+(u.active?'enabled':'disabled')+'">'+(u.active?'active':'disabled')+'</span></strong><small>'+esc(u.email+' / '+u.id)+'</small><small>Groups: '+esc((u.groups||[]).map(g=>g.name).join(', ')||'-')+'</small><small>Telegram: '+(telegram||'-')+'</small><small>Discord: '+(discord||'-')+'</small><small>Slack: '+(slack||'-')+'</small><small>Web sessions: '+esc(String((u.webSessions||[]).length))+'</small><div class="row"><button data-user-edit="'+attr(u.id)+'"'+disabledAttr('users.write')+'>Edit</button><button class="secondary" data-user-toggle="'+attr(u.id)+'"'+disabledAttr('users.write')+'>'+(u.active?'Disable':'Enable')+'</button><button class="secondary" data-user-code="'+attr(u.id)+'"'+disabledAttr('users.write')+'>Telegram code</button><button class="secondary" data-user-link="'+attr(u.id)+'"'+disabledAttr('users.write')+'>Link Telegram ID</button><button class="secondary" data-user-discord-code="'+attr(u.id)+'"'+disabledAttr('users.write')+'>Discord code</button><button class="secondary" data-user-discord-link="'+attr(u.id)+'"'+disabledAttr('users.write')+'>Link Discord ID</button><button class="secondary" data-user-slack-code="'+attr(u.id)+'"'+disabledAttr('users.write')+'>Slack code</button><button class="secondary" data-user-slack-link="'+attr(u.id)+'"'+disabledAttr('users.write')+'>Link Slack ID</button><button class="secondary" data-user-password="'+attr(u.id)+'"'+disabledAttr('users.write')+'>Set password</button><button class="danger" data-user-revoke="'+attr(u.id)+'"'+disabledAttr('users.write')+'>Revoke sessions</button></div></div>'}).join('')||'<div class="item">No users.</div>';document.getElementById('groupsList').innerHTML=(d.groups||[]).map(g=>'<div class="item"><strong>'+esc(g.name)+' '+(g.system?'<span class="chip">system</span>':'')+'</strong><small>'+esc(g.description||'')+'</small><small>Permissions: '+esc((g.permissions||[]).join(', ')||'-')+'</small><small>Agent scope: '+esc(csv(g.agentIds)||'all')+'</small><small>Workspace scope: '+esc(csv(g.workspaceRoots)||'all')+'</small><small>Telegram chat scope: '+esc(csv(g.telegramChatIds)||'all')+'</small><small>Discord channel scope: '+esc(discordScopeLabel(g.discordChannelIds)||'all')+'</small><small>Slack channel scope: '+esc(slackScopeLabel(g.slackChannelIds)||'all')+'</small><div class="row"><button class="secondary" data-group-edit="'+attr(g.id)+'"'+disabledAttr('users.write')+'>Edit group</button></div></div>').join('')||'<div class="item">No groups.</div>';document.getElementById('telegramChatsList').innerHTML=(d.telegramChats||[]).map(c=>'<div class="item"><strong>'+esc(c.title||String(c.chatId))+' <span class="adapter-status '+(c.enabled?'enabled':'disabled')+'">'+(c.enabled?'enabled':'disabled')+'</span></strong><small>'+esc('Chat ID: '+c.chatId+' / '+(c.type||'-'))+'</small><small>Groups: '+esc(groupNames(c.allowedGroupIds)||'all groups')+'</small><div class="row"><button data-chat-edit="'+attr(c.id)+'"'+disabledAttr('users.write')+'>Edit</button><button class="secondary" data-chat-toggle="'+attr(c.id)+'"'+disabledAttr('users.write')+'>'+(c.enabled?'Disable':'Enable')+'</button></div></div>').join('')||'<div class="item">No Telegram group chats registered.</div>';renderDiscordChannels(d.discordChannels||[]);renderSlackChannels(d.slackChannels||[]);bindUserButtons();bindSlackUserButtons();bindAccessCopyButtons();applyPermissions()}
