async function loadPeers(){bindPeerTabs();switchPeerTab(state.peerTab||'status');if(!can('peers.read')){document.getElementById('peerStatus').innerHTML='<div class="item">Permission required: peers.read</div>';document.getElementById('peersList').innerHTML='<div class="item">Permission required: peers.read</div>';document.getElementById('peerTopology').innerHTML='<div class="item">Permission required: peers.read</div>';document.getElementById('peerRelay').innerHTML='<div class="item">Permission required: peers.read</div>';return}setLoading('peerStatus','Loading peer status...');setLoading('peerTopology','Loading topology...');setLoading('peerRelay','Loading relay...');setLoading('peersList','Loading peers...');setLoading('peerDiscovery','Loading discovery jobs...');setLoading('peerInvites','Loading invitations...');const [d,jobsData,relayData]=await Promise.all([api('/api/peers',{local:true}),can('peers.connect')?api('/api/peers/discovery-jobs',{local:true}).catch(()=>({jobs:[]})):Promise.resolve({jobs:[]}),api('/api/peers/relay',{local:true}).catch(error=>({error:error.message||String(error)}))]);state.peers=d;state.peerRelay=relayData;state.peerDiscoveryJobs=jobsData.jobs||[];const inviteIds=new Set((d.invitations||[]).map(i=>i.id));Object.keys(state.peerInviteSecrets||{}).forEach(id=>{if(!inviteIds.has(id))delete state.peerInviteSecrets[id]});document.getElementById('peerStatus').innerHTML=peerStatusHtml(d);document.getElementById('peerTopology').innerHTML=renderPeerTopology(d);document.getElementById('peerRelay').innerHTML=renderPeerRelay(relayData);bindUiCopyButtons(document.getElementById('peerRelay'));document.getElementById('peersList').innerHTML=renderPeersTable(d.peers||[]);document.getElementById('peerDiscovery').innerHTML=peerDiscoveryJobsHtml(state.peerDiscoveryJobs);bindUiCopyButtons(document.getElementById('peerDiscovery'));document.getElementById('peerInvites').innerHTML=renderPeerInvitesTable(d.invitations||[]);ensureGlobalPeerSessionsPanel();bindPeerButtons();if(typeof applyHeaderPeerSnapshot==='function'&&state.localBootstrap){applyHeaderPeerSnapshot(d,state.localBootstrap);renderHeaderTargetMenu(state.snapshot)}applyPermissions()}
