async function loadVersion(options:any={}){const quiet=Boolean(options.quiet);const refreshJobs=options.refreshJobs!==false;const requestId=(state.versionRequestId||0)+1;state.versionRequestId=requestId;if(!quiet)setLoading('versionPanel','Checking versions...');if(refreshJobs){if(can('updates.run'))await loadAgentUpdateJobs(false);else{state.agentUpdateJobs=[];renderAgentUpdateJobs()}}const d=await api('/api/version');if(requestId!==state.versionRequestId)return;document.getElementById('versionPanel').innerHTML=renderVersionTable(d.versionChecks||{});bindAgentUpdateButtons();applyPermissions()}
