function versionRow(entry){const key=entry[0];const v=entry[1]||{};const action=versionActionButton(key,v);return '<tr>'+versionCell('Name','<span class="truncate-cell" title="'+attr(v.label||key)+'">'+esc(v.label||key)+'</span>','primary-cell')+versionCell('Status',uiBadge(versionStatusLabel(v.status),versionStatusClass(v.status)),'status-cell')+versionCell('Installed','<span class="truncate-cell" title="'+attr(v.installedLabel||'-')+'">'+esc(short(v.installedLabel||'-',90))+'</span>','version-cell')+versionCell('Latest','<span class="truncate-cell" title="'+attr(v.latestVersion||'-')+'">'+esc(short(v.latestVersion||'-',90))+'</span>','version-cell')+versionCell('Package','<span class="truncate-cell" title="'+attr(v.packageName||'-')+'">'+esc(short(v.packageName||'-',140))+'</span>','package-cell')+versionCell('Detail','<span class="truncate-cell" title="'+attr(v.detail||'')+'">'+esc(short(v.detail||'-',180))+'</span>','detail-cell')+versionCell('Actions',action?'<div class="data-table-actions">'+action+'</div>':'-','actions-cell')+'</tr>'}
