async function loadAgentUpdateJobs(showLoading=true){if(!can('updates.run')){state.agentUpdateJobs=[];const target=document.getElementById('agentUpdateJobs');if(target)target.innerHTML='<div class="item">Permission required: updates.run</div>';return}if(showLoading)setLoading('agentUpdateJobs','Loading update jobs...');const d=await api('/api/agent-updates');state.agentUpdateJobs=d.jobs||[];renderAgentUpdateJobs()}
