function renderAgentUpdateJobs(){const target=document.getElementById('agentUpdateJobs');if(!target)return;if(!can('updates.run')){target.innerHTML='<div class="item">Permission required: updates.run</div>';return}target.innerHTML=(state.agentUpdateJobs||[]).map(updateJobCard).join('')||'<div class="item">No agent update jobs.</div>';bindAgentUpdateButtons();applyPermissions()}
function updateJobCard(job){const command=[job.command].concat(job.args||[]).join(' ');const operation=job.operation||'update';const needs=job.needsInput?'<small><span class="chip warn">Input may be required</span></small>':'';const logDeleted=job.logDeletedAt?'<small>Log deleted '+esc(fmtDate(job.logDeletedAt))+'</small>':'';const deleteLogButton=job.status!=='running'&&!job.logDeletedAt?'<button class="danger mini-button" data-update-delete-log="'+attr(job.id)+'"'+disabledAttr('updates.run')+'>Delete Log</button>':'';const input=job.canInput?'<div class="update-input"><input data-update-input="'+attr(job.id)+'" placeholder="Send response to '+operation+' process"><button data-update-send="'+attr(job.id)+'" class="secondary"'+disabledAttr('updates.run')+'>Send</button><button data-update-cancel="'+attr(job.id)+'" class="danger"'+disabledAttr('updates.run')+'>Cancel</button></div>':'';return '<div class="item"><div class="update-job-header"><strong>'+esc(job.agentLabel+' '+operation)+' <span class="adapter-status '+esc(jobStatusClass(job.status))+'">'+esc(job.status)+'</span></strong><div class="row">'+deleteLogButton+'</div></div><small>'+esc(job.method+' / '+fmtDate(job.startedAt)+(job.finishedAt?' - '+fmtDate(job.finishedAt):''))+'</small><small>'+esc(command)+'</small><small>'+esc(job.error||job.summary||'')+'</small>'+logDeleted+needs+'<pre class="update-log">'+esc(job.outputTail||(job.logDeletedAt?'(log deleted)':'(waiting for output)'))+'</pre>'+input+'</div>'}
function bindAgentUpdateButtons(){document.querySelectorAll('[data-update-agent]').forEach(b=>b.onclick=()=>safe(async()=>{if(!can('updates.run')){toast('Permission required: updates.run');return}const operation=b.dataset.updateOperation||'update';if(confirm('Start '+operation+' for '+b.dataset.updateAgent+'?')){const r=await api('/api/agent-update',{method:'POST',body:JSON.stringify({agentId:b.dataset.updateAgent,operation})});upsertAgentUpdateJob(r.job);renderAgentUpdateJobs();toast(r.job.agentLabel+' '+(r.job.operation||operation)+' started',{duration:6000});loadVersion()}}));document.querySelectorAll('[data-update-send]').forEach(b=>b.onclick=()=>safe(async()=>{if(!can('updates.run')){toast('Permission required: updates.run');return}const input=document.querySelector('[data-update-input="'+cssEscape(b.dataset.updateSend)+'"]');const text=input?.value||'';if(!text.trim())return;const r=await api('/api/agent-update/'+encodeURIComponent(b.dataset.updateSend)+'/input',{method:'POST',body:JSON.stringify({input:text})});if(input)input.value='';upsertAgentUpdateJob(r.job);renderAgentUpdateJobs()}));document.querySelectorAll('[data-update-cancel]').forEach(b=>b.onclick=()=>safe(async()=>{if(!can('updates.run')){toast('Permission required: updates.run');return}if(confirm('Cancel this update job?')){const r=await api('/api/agent-update/'+encodeURIComponent(b.dataset.updateCancel)+'/cancel',{method:'POST'});upsertAgentUpdateJob(r.job);renderAgentUpdateJobs()}}));document.querySelectorAll('[data-update-delete-log]').forEach(b=>b.onclick=()=>safe(async()=>{if(!can('updates.run')){toast('Permission required: updates.run');return}if(confirm('Delete update log for '+b.dataset.updateDeleteLog+'?')){const r=await api('/api/agent-update/'+encodeURIComponent(b.dataset.updateDeleteLog)+'/log',{method:'DELETE'});state.agentUpdateJobs=(state.agentUpdateJobs||[]).filter(j=>j.id!==(r.deletedId||b.dataset.updateDeleteLog));renderAgentUpdateJobs();toast('Agent update job deleted')}}))}
